//! Tensorhub's client: generated by progenitor from the Hub's own API document (`openapi.yaml`,
//! vendored unedited by `scripts/hub-api.sh` at the commit `SOURCE` names), with the credentials
//! every cozy process speaks as: a user's device-key login and Bearer, a pod's worker capability.
//! Bulk bytes (presigned GET/PUT) are not here: TensorFS moves them.
#![forbid(unsafe_code)]
mod auth;
mod device;
mod raw;
mod wire;

#[allow(clippy::all, unused_imports)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/hub.rs"));
}

use protocol::error::{Error as Refusal, Kind};

pub use auth::{Auth, Credential};
pub use device::{Bearer, DeviceKey, Enrollment, UserSession};
pub use generated::{Client, types};
pub use progenitor_client::{ByteStream, ResponseValue};

/// A generated call's own error, before it is read as an [`Error`].
pub type CallError = progenitor_client::Error<types::Error>;

/// A refused or failed call. `Hub` carries the Hub's own typed refusal verbatim.
#[derive(Debug, thiserror::Error, serde::Serialize, serde::Deserialize)]
pub enum Error {
    #[error("{code}: {message}")]
    Hub {
        status: u16,
        code: String,
        message: String,
        remedy: String,
    },
    #[error("Tensorhub: {0}")]
    Call(String),
    /// The call's credential could not be had (a login refused, a key missing or unusable);
    /// nothing was sent.
    #[error("{0}")]
    Credential(String),
    #[error("an unusable answer: {0}")]
    Answer(String),
}

impl Error {
    /// Whether asking again may be answered: no answer, a timeout (408), rate limit (429) or
    /// server failure. A refusal, of the credential too, is final.
    pub fn retry(&self) -> bool {
        match self {
            Self::Call(_) => true,
            Self::Hub { status, .. } => Kind::of_http(*status) == Kind::Unavailable,
            _ => false,
        }
    }

    /// The one reading of a failed call as cozy's refusal: the Hub's code (also the cause),
    /// message and remedy, classed by status, `Unavailable` exactly when [`Error::retry`]. A
    /// refused credential (a login refused, a key missing, unusable or revoked, a 401) is
    /// `hub_credential`, with `login` next.
    pub fn refusal(self, login: impl FnOnce() -> String) -> Refusal {
        let (error, remedy) = match self {
            Self::Hub { status: 401, code, message, remedy } => (
                Refusal::credential("hub_credential", message).cause(code).next(login()),
                remedy,
            ),
            Self::Hub { status, code, message, remedy } => {
                (Refusal::new(Kind::of_http(status), code.clone(), message).cause(code), remedy)
            }
            Self::Call(message) => (
                Refusal::unavailable("hub_unreachable", message),
                "check this computer's internet connection, then try again".into(),
            ),
            Self::Credential(message) => {
                (Refusal::credential("hub_credential", message).next(login()), String::new())
            }
            Self::Answer(message) => (Refusal::internal("hub_answer", message), String::new()),
        };
        match remedy.is_empty() {
            true => error,
            false => error.remedy(remedy),
        }
    }
}

impl Error {
    /// A call that got no answer, in a person's words: where it went and the innermost cause
    /// (`dns error: …`, `Connection refused`), not reqwest's "error sending request for url (…)".
    pub fn unanswered(error: &reqwest::Error) -> Self {
        let mut cause: &dyn std::error::Error = error;
        while let Some(next) = cause.source() {
            cause = next;
        }
        Self::Call(match error.url() {
            Some(url) => format!("no answer from {}: {cause}", url.origin().ascii_serialization()),
            None => format!("no answer: {cause}"),
        })
    }
}

impl<E: serde::Serialize + std::fmt::Debug> From<progenitor_client::Error<E>> for Error {
    fn from(error: progenitor_client::Error<E>) -> Self {
        if let progenitor_client::Error::ErrorResponse(answer) = &error {
            let status = answer.status().as_u16();
            let body = serde_json::to_value(answer.as_ref()).unwrap_or_default();
            let field = |name: &str| body["error"][name].as_str().unwrap_or_default().to_string();
            if !field("code").is_empty() {
                return Self::Hub {
                    status,
                    code: field("code"),
                    message: field("message"),
                    remedy: field("remedy"),
                };
            }
            if let Some(code) = body["error"].as_str() {
                let message = body["error_description"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string();
                return Self::Hub {
                    status,
                    code: code.to_string(),
                    message,
                    remedy: String::new(),
                };
            }
        }
        match error {
            // The `pre` hook's own failure, typed.
            progenitor_client::Error::Custom(failed) => {
                serde_json::from_str(&failed).unwrap_or(Self::Credential(failed))
            }
            progenitor_client::Error::InvalidResponsePayload(_, why) => {
                Self::Answer(why.to_string())
            }
            progenitor_client::Error::CommunicationError(e) => Self::unanswered(&e),
            other => Self::Call(other.to_string()),
        }
    }
}
